/* Copies EK payloads from the 64DD image and records their original N64
 * address ranges. Gfx commands remain big-endian/raw; Vp and Vtx fields
 * used directly by the host interpreter are converted to native order. */
void gdx_ek_assets_fill(const unsigned char* disk, unsigned long long diskSize) {
    int i;
    unsigned int b;
    /* Table-shift bracket: gSampleBankTable entries read -0x30 at audio init
       in static-variant boots. Canary before/after this fill localizes
       whether the corruption happens inside it. */
    extern void gdx_cki(const char* s, int v);
    {
        typedef struct { unsigned int p[4]; } GdxTblHdr;
        extern unsigned char gSampleBankTable[];
        unsigned int v;
        const unsigned char* e1 = gSampleBankTable + 0x10 + 0x10; /* entries[1].romAddr */
        v = (unsigned int)e1[0] | ((unsigned int)e1[1] << 8) | ((unsigned int)e1[2] << 16) | ((unsigned int)e1[3] << 24);
        gdx_cki("[tblwatch] pre-fill entries[1].romAddr", (int) v);
    }
    if (disk == 0) { return; }
    for (i = 0; sEkAssetFills[i].dest != 0; i++) {
        if ((unsigned long long)sEkAssetFills[i].diskOffset + sEkAssetFills[i].size <= diskSize) {
            unsigned char* dest = (unsigned char*)sEkAssetFills[i].dest;
            const unsigned char* src = disk + sEkAssetFills[i].diskOffset;
            /* byte loop: this TU compiles with the decomp's headers, which
               clash with the MSVC CRT's <string.h> */
            for (b = 0; b < sEkAssetFills[i].size; b++) {
                dest[b] = src[b];
            }
            if (sEkAssetFills[i].kind == GDX_EK_ASSET_VP) {
                for (b = 0; b + 1 < sEkAssetFills[i].size; b += 2) {
                    unsigned char hi = dest[b];
                    dest[b] = dest[b + 1];
                    dest[b + 1] = hi;
                }
            } else if (sEkAssetFills[i].kind == GDX_EK_ASSET_VTX) {
                /* Vtx fields are big-endian on disk. Swap xyz, flag, and st;
                   leave the final four colour/normal bytes untouched. */
                for (b = 0; b + 16 <= sEkAssetFills[i].size; b += 16) {
                    unsigned int k;
                    for (k = 0; k < 12; k += 2) {
                        unsigned char hi = dest[b + k];
                        dest[b + k] = dest[b + k + 1];
                        dest[b + k + 1] = hi;
                    }
                }
            } else if (sEkAssetFills[i].kind == GDX_EK_ASSET_GFX) {
                gdx_register_host_raw_n64_range(dest, sEkAssetFills[i].size);
            }
            if (sEkAssetFills[i].n64Address != 0) {
                gdx_register_n64_address_range(sEkAssetFills[i].n64Address, dest, sEkAssetFills[i].size);
            }
            gdx_register_host_pointer_stub(dest, sEkAssetFills[i].size);
            /* M-B: EK assets fill host arrays (not RDRAM), so they pass the
               !IsRdramHostPointer guard and are overridable through the existing
               Tier-B path once the buffer carries its ek/<symbol> key. */
            GDiffuser_RegisterLoadedAssetBuffer(dest, sEkAssetFills[i].size, sEkAssetFills[i].key);
        }
    }
    {
        extern unsigned char gSampleBankTable[];
        unsigned int v;
        const unsigned char* e1 = gSampleBankTable + 0x10 + 0x10;
        v = (unsigned int)e1[0] | ((unsigned int)e1[1] << 8) | ((unsigned int)e1[2] << 16) | ((unsigned int)e1[3] << 24);
        gdx_cki("[tblwatch] post-fill entries[1].romAddr", (int) v);
    }
}

/* Returns the byte extent of a generated disk-resident segmented image. */
unsigned int gdx_ek_segment_image_size(unsigned char segment) {
    unsigned int required = 0;
    int i;
    for (i = 0; sEkAssetFills[i].dest != 0; i++) {
        unsigned int address = sEkAssetFills[i].n64Address;
        unsigned int offset;
        unsigned int end;
        if ((address >> 24) != segment) { continue; }
        offset = address & 0x00FFFFFFU;
        end = offset + sEkAssetFills[i].size;
        if (end >= offset && end > required) { required = end; }
    }
    return required;
}

/* Rebuilds one disk-resident segment in its original address layout while
 * applying only the host-order conversions required by direct consumers. */
int gdx_ek_segment_image_fill(unsigned char segment, const unsigned char* disk,
                              unsigned long long diskSize, unsigned char* dest,
                              unsigned int capacity) {
    unsigned int required = gdx_ek_segment_image_size(segment);
    unsigned int b;
    int i;
    if (disk == 0 || dest == 0 || required == 0 || required > capacity) { return 0; }
    for (b = 0; b < required; b++) { dest[b] = 0; }
    for (i = 0; sEkAssetFills[i].dest != 0; i++) {
        unsigned int address = sEkAssetFills[i].n64Address;
        unsigned int offset;
        unsigned char* item;
        const unsigned char* src;
        if ((address >> 24) != segment) { continue; }
        offset = address & 0x00FFFFFFU;
        if (offset > capacity || sEkAssetFills[i].size > capacity - offset ||
            (unsigned long long)sEkAssetFills[i].diskOffset + sEkAssetFills[i].size > diskSize) {
            return 0;
        }
        item = dest + offset;
        src = disk + sEkAssetFills[i].diskOffset;
        for (b = 0; b < sEkAssetFills[i].size; b++) { item[b] = src[b]; }
        if (sEkAssetFills[i].kind == GDX_EK_ASSET_VP) {
            for (b = 0; b + 1 < sEkAssetFills[i].size; b += 2) {
                unsigned char hi = item[b]; item[b] = item[b + 1]; item[b + 1] = hi;
            }
        } else if (sEkAssetFills[i].kind == GDX_EK_ASSET_VTX) {
            for (b = 0; b + 16 <= sEkAssetFills[i].size; b += 16) {
                unsigned int k;
                for (k = 0; k < 12; k += 2) {
                    unsigned char hi = item[b + k];
                    item[b + k] = item[b + k + 1]; item[b + k + 1] = hi;
                }
            }
        } else if (sEkAssetFills[i].kind == GDX_EK_ASSET_GFX) {
            for (b = 0; b + 3 < sEkAssetFills[i].size; b += 4) {
                unsigned char b0 = item[b]; unsigned char b1 = item[b + 1];
                item[b] = item[b + 3]; item[b + 1] = item[b + 2];
                item[b + 2] = b1; item[b + 3] = b0;
            }
            gdx_register_host_n64_command_range(item, sEkAssetFills[i].size);
        }
    }
    return 1;
}
